using System.IO;
using System.Diagnostics;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Threading;
namespace DesktopBox;
internal sealed class Entry {
 public string Path {get;init;}=""; public string Name=>System.IO.Path.GetFileName(Path);public bool Exists=>File.Exists(Path)||Directory.Exists(Path);
 public string Type=>Directory.Exists(Path)?"文件夹":System.IO.Path.GetExtension(Path);public string Size {get{try{return File.Exists(Path)?new FileInfo(Path).Length.ToString("N0")+" B":"";}catch{return "";}}}public string Modified {get{try{return File.GetLastWriteTime(Path).ToString("yyyy-MM-dd HH:mm");}catch{return "";}}}
 public ImageSource? Icon=>ShellIcons.Get(Path);public override string ToString()=>Name;
}
internal sealed class BoxWindow:Window {
 readonly Program app; internal BoxConfig Config; readonly ListView entries=new();readonly TextBlock status=new(){TextWrapping=TextWrapping.Wrap,FontSize=11};readonly TextBlock title=new(){FontSize=17,FontWeight=FontWeights.SemiBold};FileSystemWatcher? watcher;readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromSeconds(2)};bool closing;
 internal BoxWindow(Program app,BoxConfig config){this.app=app;Config=config;Title=config.Name;Width=Math.Max(300,config.Width);Height=Math.Max(220,config.Height);Left=config.X;Top=config.Y;MinWidth=300;MinHeight=220;WindowStyle=WindowStyle.None;ResizeMode=config.Locked?ResizeMode.NoResize:ResizeMode.CanResizeWithGrip;ShowInTaskbar=false;Background=new SolidColorBrush(Color.FromArgb(155,29,40,56));Foreground=Brushes.White;
 var root=new DockPanel{Margin=new Thickness(14)};Content=root;var header=new DockPanel{Margin=new Thickness(0,0,0,10)};DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);var menuButton=Manager.Button("⋯",()=>ShowMenu());DockPanel.SetDock(menuButton,Dock.Right);header.Children.Add(menuButton);title.Text=config.Name;header.Children.Add(title);title.MouseLeftButtonDown+=(_,e)=>{if(!config.Locked&&e.ClickCount==1)DragMove();};
 DockPanel.SetDock(status,Dock.Bottom);root.Children.Add(status);entries.Background=Brushes.Transparent;entries.Foreground=Brushes.White;entries.BorderThickness=new Thickness(0);entries.SelectionMode=SelectionMode.Extended;root.Children.Add(entries);AllowDrop=true;DragOver+=(_,e)=>{e.Effects=e.Data.GetDataPresent(DataFormats.FileDrop)?(Config.Folder==null?DragDropEffects.Link:DragDropEffects.Move):DragDropEffects.None;e.Handled=true;};Drop+=OnDrop;entries.MouseDoubleClick+=(_,_)=>{if(entries.SelectedItem is Entry item)Try(()=>Process.Start(new ProcessStartInfo(item.Path){UseShellExecute=true}));};entries.ContextMenu=new ContextMenu();entries.ContextMenu.Opened+=(_,_)=>FileMenu();
 SourceInitialized+=(_,_)=>Native.Glass(this);LocationChanged+=(_,_)=>SaveLayout();SizeChanged+=(_,_)=>SaveLayout();Closing+=(_,e)=>{if(!closing){e.Cancel=true;Hide();}};timer.Tick+=(_,_)=>{Refresh();if(Config.Folder==null)foreach(var path in Config.Entries)try{DesktopIcons.EnsureHidden(path);}catch(Exception ex){status.Text="图标隐藏失效："+ex.Message;}};timer.Start();BindWatcher();Refresh();if(Config.Folder==null)foreach(var path in Config.Entries)Try(()=>DesktopIcons.Hide(path));}
 void SaveLayout(){if(!IsLoaded)return;Config.X=Left;Config.Y=Top;Config.Width=ActualWidth;Config.Height=ActualHeight;app.Save();}
 void BindWatcher(){watcher?.Dispose();watcher=null;if(Config.Folder!=null&&Directory.Exists(Config.Folder)){try{watcher=new FileSystemWatcher(Config.Folder){NotifyFilter=NotifyFilters.FileName|NotifyFilters.DirectoryName|NotifyFilters.Size|NotifyFilters.LastWrite};watcher.Changed+=Changed;watcher.Created+=Changed;watcher.Deleted+=Changed;watcher.Renamed+=Changed;watcher.EnableRaisingEvents=true;}catch(Exception ex){status.Text=ex.Message;}}}
 void Changed(object s,FileSystemEventArgs e)=>Dispatcher.BeginInvoke(Refresh);
 internal void Refresh(){try{var selected=entries.SelectedItems.Cast<Entry>().Select(x=>x.Path).ToHashSet(StringComparer.OrdinalIgnoreCase);IEnumerable<string> paths=Config.Entries;if(Config.Folder!=null){if(!Directory.Exists(Config.Folder)){entries.ItemsSource=null;status.Text="映射路径失效，请通过 ⋯ 重新绑定。";return;}paths=Directory.EnumerateFileSystemEntries(Config.Folder);}var items=paths.OrderBy(p=>System.IO.Path.GetFileName(p),StringComparer.CurrentCultureIgnoreCase).Select(p=>new Entry{Path=p}).ToList();entries.ItemsSource=items;foreach(var item in items.Where(i=>selected.Contains(i.Path)))entries.SelectedItems.Add(item);SetView();status.Text=(Config.Folder==null?"虚拟入口 · 文件位置不变":"映射 · 拖入移动真实文件")+" · "+items.Count+" 项";}catch(Exception ex){status.Text="读取失败："+ex.Message;}}
 void SetView(){if(Config.View=="详细信息"){var view=new GridView();foreach(var c in new[]{("名称","Name",170d),("类型","Type",65d),("大小","Size",80d),("修改时间","Modified",125d)})view.Columns.Add(new GridViewColumn{Header=c.Item1,DisplayMemberBinding=new System.Windows.Data.Binding(c.Item2),Width=c.Item3});entries.View=view;entries.ItemsPanel=new ItemsPanelTemplate(new FrameworkElementFactory(typeof(VirtualizingStackPanel)));entries.ItemTemplate=null;}else{entries.View=null;var p=new FrameworkElementFactory(Config.View=="图标"?typeof(WrapPanel):typeof(VirtualizingStackPanel));entries.ItemsPanel=new ItemsPanelTemplate(p);var stack=new FrameworkElementFactory(typeof(StackPanel));stack.SetValue(FrameworkElement.WidthProperty,Config.View=="图标"?100d:250d);stack.SetValue(FrameworkElement.MarginProperty,new Thickness(4,8,4,8));if(Config.View=="图标"){var icon=new FrameworkElementFactory(typeof(System.Windows.Controls.Image));icon.SetBinding(System.Windows.Controls.Image.SourceProperty,new System.Windows.Data.Binding("Icon"));icon.SetValue(FrameworkElement.HeightProperty,32d);icon.SetValue(FrameworkElement.WidthProperty,32d);icon.SetValue(FrameworkElement.HorizontalAlignmentProperty,HorizontalAlignment.Center);stack.AppendChild(icon);}var text=new FrameworkElementFactory(typeof(TextBlock));text.SetBinding(TextBlock.TextProperty,new System.Windows.Data.Binding("Name"));text.SetValue(TextBlock.TextTrimmingProperty,TextTrimming.CharacterEllipsis);stack.AppendChild(text);entries.ItemTemplate=new DataTemplate{VisualTree=stack};}}
 void ShowMenu(){var m=new ContextMenu();Add(m,"改名",()=>{var n=Manager.Ask(this,"盒子名称",Config.Name);if(!string.IsNullOrWhiteSpace(n)){Config.Name=n;title.Text=n;Title=n;app.Save();}});Add(m,Config.Locked?"解锁位置":"锁定位置",()=>{Config.Locked=!Config.Locked;ResizeMode=Config.Locked?ResizeMode.NoResize:ResizeMode.CanResizeWithGrip;app.Save();});foreach(var v in new[]{"图标","列表","详细信息"})Add(m,"视图 · "+v,()=>{Config.View=v;app.Save();Refresh();});if(Config.Folder!=null){Add(m,"重新绑定文件夹",()=>{var f=Manager.PickFolder();if(f==null)return;Config.Folder=f;BindWatcher();app.Save();Refresh();});Add(m,"打开映射文件夹",()=>Try(()=>Process.Start(new ProcessStartInfo(Config.Folder){UseShellExecute=true})));}Add(m,"删除盒子（保留文件）",()=>app.Delete(this));m.IsOpen=true;}
 static void Add(ContextMenu m,string text,Action action){var i=new MenuItem{Header=text};i.Click+=(_,_)=>action();m.Items.Add(i);}
 void FileMenu(){var m=entries.ContextMenu!;m.Items.Clear();if(entries.SelectedItem is not Entry item)return;Add(m,"打开",()=>Try(()=>Process.Start(new ProcessStartInfo(item.Path){UseShellExecute=true})));Add(m,"在资源管理器中显示",()=>Try(()=>Process.Start(new ProcessStartInfo("explorer.exe","/select,\""+item.Path+"\""){UseShellExecute=true})));if(Config.Folder==null)Add(m,"移出盒子（文件不移动）",()=>{foreach(var i in entries.SelectedItems.Cast<Entry>().ToArray()){try{DesktopIcons.Restore(i.Path);Config.Entries.Remove(i.Path);}catch(Exception ex){MessageBox.Show("恢复失败，入口保留："+ex.Message);}}app.Save();Refresh();});}
 void OnDrop(object s,DragEventArgs e){if(e.Data.GetData(DataFormats.FileDrop) is not string[] paths)return;var failures=new List<string>();foreach(var path in paths){try{if(Config.Folder==null){if(!File.Exists(path)&&!Directory.Exists(path))throw new IOException("文件不存在");if(!Config.Entries.Contains(path,StringComparer.OrdinalIgnoreCase)){if(app.Windows.Any(w=>w!=this&&w.Config.Entries.Contains(path,StringComparer.OrdinalIgnoreCase)))throw new IOException("该入口已在其他普通盒子中，请先移出。");DesktopIcons.Hide(path);Config.Entries.Add(path);}}else FileActions.MoveInto(path,Config.Folder);}catch(Exception ex){failures.Add(System.IO.Path.GetFileName(path)+"："+ex.Message);}}app.Save();Refresh();if(failures.Count>0)MessageBox.Show(string.Join("\n",failures),"部分项目未收纳");e.Handled=true;}
 void Try(Action action){try{action();}catch(Exception ex){MessageBox.Show(ex.Message,"操作失败");}}
 internal void DisposeAndClose(){closing=true;watcher?.Dispose();timer.Stop();if(Config.Folder==null)foreach(var p in Config.Entries)try{DesktopIcons.Restore(p);}catch(Exception ex){MessageBox.Show("图标恢复失败，恢复记录已保留："+ex.Message);}Close();}
}




